-- RootishArrayStack：未使用槽位和块目录的平方根级额外空间。
INSERT INTO knowledge_point (name, description, course_id, parent_id, content_key, content_source, content_version, content_review_status, sort_order, deleted)
SELECT 'RootishArrayStack 的浪费空间界', '最多两个末尾块不满，块数 r=O(sqrt(n))，因此未用槽位与块目录的额外空间为 O(sqrt(n))。', course.id, parent.id, 'ods-rootisharraystack-space', 'AISTU', 1, 'REVIEWED', 33, 0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-stacks-queues-arrays' LEFT JOIN knowledge_point existing ON existing.content_key='ods-rootisharraystack-space' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id, content_key, content_version, review_status, title, lesson_json, check_json)
SELECT point.id,'ods-rootisharraystack-space',1,'REVIEWED','RootishArrayStack 的浪费空间界',JSON_OBJECT('summary','shrink 保证最多两个末尾块不满，因此 (r-2)(r-1)/2≤n，得到 r=O(sqrt(n))。末尾空槽和保存 r 个块引用都为 O(r)，总浪费空间为 O(sqrt(n))。','steps',JSON_ARRAY('收缩规则限制未满块只出现在最后两个块','由累计容量不等式推出 r=O(sqrt(n))','最后两个块的空槽至多为 2r-1','块目录和空槽合计仍为 O(sqrt(n))'),'prerequisite',JSON_OBJECT('contentKey','ods-rootisharraystack-grow-shrink','title','RootishArrayStack 的块增长与收缩','description','先理解末尾多余块会被删除。'),'nextStep',JSON_OBJECT('contentKey','ods-rootisharraystack-performance','title','RootishArrayStack 的时间与空间复杂度','description','继续汇总时间界与空间权衡。')),JSON_OBJECT('id','rootisharraystack-space-v1','prompt','为什么 RootishArrayStack 的额外空间是 O(sqrt(n))？','options',JSON_ARRAY(JSON_OBJECT('id','BLOCK_COUNT','text','最多两个末尾块不满且块数 r 为 O(sqrt(n))'),JSON_OBJECT('id','NO_EMPTY_SLOT','text','每个数组块始终完全填满')),'correctOptionId','BLOCK_COUNT','correctExplanation','正确：少量末尾未满块与块目录都随 r 增长，而 r 受平方根界限制。','incorrectExplanation','不正确：最后一两个块可以未满；空间界不是零空槽。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='ods-rootisharraystack-space' AND existing.content_version=1 WHERE point.content_key='ods-rootisharraystack-space' AND existing.id IS NULL;
